'use client';

import { useEffect, useId, useRef, type ReactNode } from 'react';
import './animated-checkbox.css';

export interface AnimatedCheckboxProps {
  checked: boolean;
  /** Shows a dash: some, but not all, of a group is checked. */
  indeterminate?: boolean;
  onChange: (checked: boolean) => void;
  children: ReactNode;
  className?: string;
}

/**
 * A native checkbox (so forms, labels and screen readers work as usual)
 * with a drawn check mark and a drawn dash for the mixed state.
 */
export function AnimatedCheckbox({
  checked,
  indeterminate = false,
  onChange,
  children,
  className = '',
}: AnimatedCheckboxProps) {
  const input = useRef<HTMLInputElement>(null);
  const id = useId();

  useEffect(() => {
    if (input.current) input.current.indeterminate = indeterminate;
  }, [indeterminate]);

  const state = indeterminate ? 'mixed' : checked ? 'checked' : 'unchecked';
  return (
    <label className={`mg-check ${className}`} htmlFor={id} data-state={state}>
      <input
        ref={input}
        id={id}
        type='checkbox'
        className='mg-check__input'
        checked={checked}
        onChange={(event) => onChange(event.target.checked)}
      />
      <span className='mg-check__box' aria-hidden='true'>
        <svg viewBox='0 0 20 20'>
          <path
            className='mg-check__tick'
            d='M4.5 10.5 L8.5 14.5 L15.5 6'
            pathLength={1}
          />
          <path className='mg-check__dash' d='M5 10 H15' pathLength={1} />
        </svg>
      </span>
      <span className='mg-check__label'>{children}</span>
    </label>
  );
}

.mg-check {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 44px;
  color: var(--mg-text, #ffffff);
  cursor: pointer;
}

/* The real checkbox sits on top of the drawn box, invisible but clickable. */
.mg-check__input {
  position: absolute;
  top: 50%;
  left: 0;
  width: 24px;
  height: 24px;
  margin: -12px 0 0;
  opacity: 0;
  cursor: pointer;
}

.mg-check__box {
  display: grid;
  flex: none;
  place-items: center;
  width: 24px;
  height: 24px;
  border: 2px solid #5c5c5c;
  border-radius: 6px;
  background: #121212;
  transition:
    background-color 200ms ease,
    border-color 200ms ease;
}

.mg-check__input:focus-visible + .mg-check__box {
  outline: 3px solid var(--mg-accent-text, #dce9f7);
  outline-offset: 2px;
}

.mg-check[data-state='checked'] .mg-check__box,
.mg-check[data-state='mixed'] .mg-check__box {
  border-color: var(--mg-accent-text, #dce9f7);
  background: var(--mg-accent, #eaf2fb);
}

.mg-check__box svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: #080808;
  stroke-width: 2.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.mg-check__tick,
.mg-check__dash {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  transition: stroke-dashoffset 260ms ease-out;
}

.mg-check[data-state='checked'] .mg-check__tick,
.mg-check[data-state='mixed'] .mg-check__dash {
  stroke-dashoffset: 0;
  transition-delay: 60ms;
}

@media (prefers-reduced-motion: reduce) {
  .mg-check__box,
  .mg-check__tick,
  .mg-check__dash {
    transition: none;
  }
}
